select jsonb_build_object('fingerprints',(select jsonb_object_agg(name,value) from (select 'listings' name,jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) value from public.listings t union all select 'user_favorites',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.user_favorites t union all select 'shopping_offers',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.shopping_offers t union all select 'pinpoint_entries',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.pinpoint_entries t union all select 'service_submissions',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.service_submissions t union all select 'discovery_media',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.discovery_media t union all select 'saved_specials',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.saved_specials t union all select 'discovery_places',jsonb_build_object('count',count(*),'md5',md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),''))) from public.discovery_places t) f),'functions',(select jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('definition',pg_get_functiondef(p.oid),'acl',p.proacl::text)) from pg_proc p where p.oid=any(array['private.discovery_card_validate(jsonb,boolean,boolean)'::regprocedure,'public.discovery_media_manage(text,text,uuid,integer,uuid,text,integer)'::regprocedure,'private.pinpoint_offer_write(text,uuid,integer,jsonb,uuid)'::regprocedure,'private.pinpoint_entry_write(text,text,uuid,integer,jsonb,uuid)'::regprocedure]))) as state;
